package githubrunner

import("context";"encoding/json";"errors";"fmt";"net/http";"net/url";"strconv";"strings";"time";"github.com/example-user/runnerhub/internal/core")
type Repository struct{ID int64 `json:"id"`;FullName string `json:"fullName"`;Private bool `json:"private"`;DefaultBranch string `json:"defaultBranch"`}
type RunnerGroup struct{ID int64 `json:"id"`;Name string `json:"name"`;Visibility string `json:"visibility"`;Default bool `json:"default,omitempty"`;Inherited bool `json:"inherited,omitempty"`;AllowsPublicRepositories bool `json:"allows_public_repositories"`;RestrictedToWorkflows bool `json:"restricted_to_workflows"`;SelectedWorkflows []string `json:"selected_workflows,omitempty"`;WorkflowRestrictionsReadOnly bool `json:"workflow_restrictions_read_only,omitempty"`}
type Catalog interface{ListRepositories(context.Context,core.GitHubScope)([]Repository,error);GetRepository(context.Context,string,string)(Repository,error);ListRunnerGroups(context.Context,string)([]RunnerGroup,error);GetRunnerGroup(context.Context,string,int64)(RunnerGroup,error);ListRunnerGroupRepositories(context.Context,string,int64)([]Repository,error)}
type HTTPCatalog struct{client *http.Client;tokens TokenSource;base *url.URL;apiVersion string}
func NewHTTPCatalog(client *http.Client,tokens TokenSource,base string)(*HTTPCatalog,error){if tokens==nil{return nil,errors.New("token source required")};if client==nil{client=&http.Client{Timeout:30*time.Second}};u,err:=parseAPIBase(base);if err!=nil{return nil,err};return &HTTPCatalog{client:client,tokens:tokens,base:u,apiVersion:defaultAPIVersion},nil}
func(c *HTTPCatalog)ListRepositories(ctx context.Context,scope core.GitHubScope)([]Repository,error){token,err:=c.tokens.Token(ctx,scope);if err!=nil{return nil,err};var out []Repository;for page:=1;;page++{var response struct{Repositories []struct{ID int64 `json:"id"`;FullName string `json:"full_name"`;Private bool `json:"private"`;DefaultBranch string `json:"default_branch"`} `json:"repositories"`};path:="/installation/repositories?per_page=100&page="+strconv.Itoa(page);if err:=c.get(ctx,path,token,&response);err!=nil{return nil,err};for _,r:=range response.Repositories{out=append(out,Repository{ID:r.ID,FullName:r.FullName,Private:r.Private,DefaultBranch:r.DefaultBranch})};if len(response.Repositories)<100{break}};return out,nil}
func(c *HTTPCatalog)GetRepository(ctx context.Context,owner,repo string)(Repository,error){scope:=core.GitHubScope{Kind:core.ScopeRepository,Owner:owner,Repository:repo};token,err:=c.tokens.Token(ctx,scope);if err!=nil{return Repository{},err};var r struct{ID int64 `json:"id"`;FullName string `json:"full_name"`;Private bool `json:"private"`;DefaultBranch string `json:"default_branch"`};if err:=c.get(ctx,"/repos/"+url.PathEscape(owner)+"/"+url.PathEscape(repo),token,&r);err!=nil{return Repository{},err};return Repository{ID:r.ID,FullName:r.FullName,Private:r.Private,DefaultBranch:r.DefaultBranch},nil}
func(c *HTTPCatalog)ListRunnerGroups(ctx context.Context,org string)([]RunnerGroup,error){scope:=core.GitHubScope{Kind:core.ScopeOrganization,Owner:org};token,err:=c.tokens.Token(ctx,scope);if err!=nil{return nil,err};var out []RunnerGroup;for page:=1;;page++{var response struct{RunnerGroups []RunnerGroup `json:"runner_groups"`};path:="/orgs/"+url.PathEscape(org)+"/actions/runner-groups?per_page=100&page="+strconv.Itoa(page);if err:=c.get(ctx,path,token,&response);err!=nil{return nil,err};out=append(out,response.RunnerGroups...);if len(response.RunnerGroups)<100{break}};return out,nil}
func(c *HTTPCatalog)GetRunnerGroup(ctx context.Context,org string,id int64)(RunnerGroup,error){if strings.TrimSpace(org)==""||id<=0{return RunnerGroup{},errors.New("organization and runner group id required")};scope:=core.GitHubScope{Kind:core.ScopeOrganization,Owner:org};token,err:=c.tokens.Token(ctx,scope);if err!=nil{return RunnerGroup{},err};var g RunnerGroup;if err:=c.get(ctx,"/orgs/"+url.PathEscape(org)+"/actions/runner-groups/"+strconv.FormatInt(id,10),token,&g);err!=nil{return RunnerGroup{},err};return g,nil}
func(c *HTTPCatalog)ListRunnerGroupRepositories(ctx context.Context,org string,id int64)([]Repository,error){if strings.TrimSpace(org)==""||id<=0{return nil,errors.New("organization and runner group id required")};scope:=core.GitHubScope{Kind:core.ScopeOrganization,Owner:org};token,err:=c.tokens.Token(ctx,scope);if err!=nil{return nil,err};var out []Repository;for page:=1;;page++{var response struct{Repositories []struct{ID int64 `json:"id"`;FullName string `json:"full_name"`;Private bool `json:"private"`;DefaultBranch string `json:"default_branch"`} `json:"repositories"`};path:="/orgs/"+url.PathEscape(org)+"/actions/runner-groups/"+strconv.FormatInt(id,10)+"/repositories?per_page=100&page="+strconv.Itoa(page);if err:=c.get(ctx,path,token,&response);err!=nil{return nil,err};for _,r:=range response.Repositories{out=append(out,Repository{ID:r.ID,FullName:r.FullName,Private:r.Private,DefaultBranch:r.DefaultBranch})};if len(response.Repositories)<100{break}};return out,nil}
func(c *HTTPCatalog)get(ctx context.Context,path,token string,out any)error{endpoint,err:=apiEndpoint(c.base,path);if err!=nil{return err};req,err:=http.NewRequestWithContext(ctx,http.MethodGet,endpoint,nil);if err!=nil{return err};req.Header.Set("Authorization","Bearer "+token);req.Header.Set("Accept","application/vnd.github+json");req.Header.Set("X-GitHub-Api-Version",c.apiVersion);resp,err:=c.client.Do(req);if err!=nil{return err};defer resp.Body.Close();if resp.StatusCode<200||resp.StatusCode>=300{return fmt.Errorf("github catalog request returned %d",resp.StatusCode)};return json.NewDecoder(resp.Body).Decode(out)}
